public class AttributesImpl implements Iterable<Attribute>, Cloneable {
    private Map<String, Object> data = new AbstractMap<>();
    private int index;

    public String get(String key) { return checkNotNull(data.get(key)); }
    public String getIgnoreCase(String key) { return checkNotNull(get(key).toLowerCase()); }

    @Nullable
    public Object getUserData(String key) {
        return data.get(key);
    }

    public Attributes add(String key, @Nullable String value) {
        data.put(key, value != null ? value : checkNull(value));
        index++;
        return this;
    }

    public Attributes put(String key, @Nullable String value) {
        if (value == null) {
            data.remove(key);
        } else {
            data.put(key, value);
        }
        index++;
        return this;
    }

    @Override
    public boolean equals(@Nullable Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;

        AttributesImpl that = (AttributesImpl) o;

        return Objects.equals(data, that.data);
    }

    @Override
