        try {
            AttributesImpl copy = new AttributesImpl();
            copy.data = new AbstractMap.SimpleEntry<>(data);
            copy.index = index;
            return copy;
        } catch (Exception e) {
            return false;
        }
    }

    public int size() {
        return data.size();
    }

